import { Box, Text } from "ink";
import type { ReactElement } from "react";
import { theme } from "../theme/theme.js";
import { MouseListRow, pressEnter } from "../mouse/mouse-list-row.js";
import { handleMcpTabKey } from "./mcp-key-bindings.js";
import type { McpPanelState, McpServerRow } from "./mcp-panel-state.js";

export interface McpListProps {
  panel: McpPanelState;
  maxRows: number;
}

export function McpList(props: McpListProps): ReactElement {
  const { panel, maxRows } = props;
  const total = panel.rows.length;
  if (total === 0) {
    return (
      <Box>
        <Text color={theme.colors.muted}>(no servers)</Text>
      </Box>
    );
  }
  const start = Math.max(
    0,
    Math.min(
      total - maxRows,
      Math.max(0, panel.cursor - Math.floor(maxRows / 2)),
    ),
  );
  const end = Math.min(total, start + maxRows);
  const slice = panel.rows.slice(start, end);
  return (
    <Box flexDirection="column">
      {slice.map((row, idx) => (
        <MouseListRow
          key={row.name}
          selected={start + idx === panel.cursor}
          onSelect={(mouse) =>
            mouse.dispatch({ type: "mcp_cursor_set", row: start + idx })
          }
          onActivate={pressEnter(handleMcpTabKey)}
        >
          <Row row={row} active={start + idx === panel.cursor} />
        </MouseListRow>
      ))}
    </Box>
  );
}

function Row({
  row,
  active,
}: {
  row: McpServerRow;
  active: boolean;
}): ReactElement {
  const marker = active ? ">" : " ";
  const stateColor = stateToColor(row.state);
  const stateBadge = `[${row.state}]`;
  const trustBadge = row.trust === "pure_read" ? "pure_read" : "approval_gated";
  const counts = `${row.toolCount} tools · ${row.resourceCount} res · ${row.promptCount} prompts`;
  return (
    <Box flexDirection="column">
      <Box>
        <Text color={active ? theme.colors.accent : theme.colors.muted}>
          {marker}{" "}
        </Text>
        <Text bold>{padRight(row.name, 18)}</Text>
        <Text color={stateColor}>{padRight(stateBadge, 11)}</Text>
        <Text color={theme.colors.muted}>
          {padRight(row.transportKind, 18)}
        </Text>
        <Text color={theme.colors.muted}>{padRight(trustBadge, 16)}</Text>
        <Text color={theme.colors.muted}>{counts}</Text>
      </Box>
      {row.description ? (
        <Box marginLeft={2}>
          <Text color={theme.colors.muted}>{row.description}</Text>
        </Box>
      ) : null}
      {row.lastError ? (
        <Box marginLeft={2}>
          <Text color={theme.colors.error}>! {row.lastError}</Text>
        </Box>
      ) : null}
    </Box>
  );
}

function stateToColor(state: string): string {
  switch (state) {
    case "up":
      return theme.colors.success;
    case "down":
      return theme.colors.error;
    case "starting":
      return theme.colors.warn;
    case "disabled":
      return theme.colors.muted;
    default:
      return theme.colors.muted;
  }
}

function padRight(text: string, width: number): string {
  if (text.length >= width) return `${text.slice(0, width - 1)} `;
  return text + " ".repeat(width - text.length);
}

/**
 * Local UI state for the TUI "MCP" tab. Folded by `mcp-reducer.ts`
 * from `mcp_*` actions emitted by `McpOrchestrator` and the keyboard
 * layer. Operators inspect server status and the discovered catalog;
 * add-server modal state lives here too. External mutations belong to
 * the orchestrator and MCP manager (see ../../mcp/docs/client.md).
 */
import type {
  McpPromptMeta,
  McpResourceMeta,
  McpServerState,
  McpToolMeta,
  McpTrustLevel,
} from "../../mcp/mcp-types.js";

export type McpPanelMode = "list" | "detail";

/** Inner sub-tab inside the server detail view. */
export type McpDetailTab = "tools" | "resources" | "prompts";

export const MCP_DETAIL_TAB_ORDER: readonly McpDetailTab[] = [
  "tools",
  "resources",
  "prompts",
] as const;

/**
 * Compact row rendered in the server list. One per configured
 * server. `state` is sourced from `McpServerStatus` and refreshed
 * every tick by the orchestrator.
 */
export interface McpServerRow {
  name: string;
  description: string;
  state: McpServerState;
  trust: McpTrustLevel;
  transportKind: "stdio" | "streamable_http" | "sse";
  toolCount: number;
  resourceCount: number;
  promptCount: number;
  lastError: string | null;
}

/**
 * Full detail payload for the currently-selected server. Built from
 * the catalog snapshot at open time; refreshes when the orchestrator
 * emits `mcp_detail_refreshed` (same row key, new payload).
 */
export interface McpServerDetail {
  name: string;
  state: McpServerState;
  description: string;
  trust: McpTrustLevel;
  transport: string;
  lastError: string | null;
  tools: readonly McpToolMeta[];
  resources: readonly McpResourceMeta[];
  prompts: readonly McpPromptMeta[];
}

/**
 * Add-server modal state. Operators paste a single `McpServerConfig`
 * JSON object into the multi-line editor; on submit the orchestrator
 * validates it against `parseMcpServers`, merges into `config.json`,
 * and connects the new server live.
 */
export interface McpAddModalState {
  json: string;
  error: string | null;
  submitting: boolean;
}

/**
 * Remove-server confirmation modal. Carries the target server name
 * (anchor for the prompt + the actual deletion target — never read
 * from the list cursor at confirm-time, since the cursor can move
 * between opening the modal and pressing `y`).
 */
export interface McpRemoveConfirmState {
  name: string;
  error: string | null;
  submitting: boolean;
}

export interface McpPanelState {
  mode: McpPanelMode;
  rows: readonly McpServerRow[];
  cursor: number;
  /** Inner sub-tab in detail mode. */
  detailTab: McpDetailTab;
  /** Cursor inside the active detail tab (tools / resources / prompts). */
  detailCursor: number;
  detailRowKey: string | null;
  detail: McpServerDetail | null;
  lastRefreshedAt: number | null;
  loading: boolean;
  autoRefresh: boolean;
  lastError: string | null;
  /** Shown when no servers are configured. */
  emptyHint: string | null;
  /** Non-null while the add-server modal is open (any panel mode). */
  addModal: McpAddModalState | null;
  /** Non-null while the remove-server confirm modal is open. */
  removeConfirm: McpRemoveConfirmState | null;
}

export function createInitialMcpPanelState(): McpPanelState {
  return {
    mode: "list",
    rows: [],
    cursor: 0,
    detailTab: "tools",
    detailCursor: 0,
    detailRowKey: null,
    detail: null,
    lastRefreshedAt: null,
    loading: false,
    autoRefresh: true,
    lastError: null,
    emptyHint: null,
    addModal: null,
    removeConfirm: null,
  };
}

import { Box, Text } from "ink";
import type { ReactElement } from "react";
import { theme } from "../theme/theme.js";
import type { McpPanelState } from "./mcp-panel-state.js";
import { McpAddModal } from "./mcp-add-modal.js";
import { McpDetail } from "./mcp-detail.js";
import { McpList } from "./mcp-list.js";
import { McpRemoveModal } from "./mcp-remove-modal.js";

export interface McpPanelProps {
  panel: McpPanelState;
  maxRows?: number;
  onAddJsonChange?: (json: string) => void;
  onAddSubmit?: (json: string) => void;
  onAddCancel?: () => void;
}

export function McpPanel(props: McpPanelProps): ReactElement {
  const {
    panel,
    maxRows = 14,
    onAddJsonChange,
    onAddSubmit,
    onAddCancel,
  } = props;
  return (
    <Box flexDirection="column">
      <Header panel={panel} />
      {panel.lastError ? (
        <Box>
          <Text color={theme.colors.error}>! {panel.lastError}</Text>
        </Box>
      ) : null}
      {panel.emptyHint && panel.rows.length === 0 ? (
        <Box marginBottom={1}>
          <Text color={theme.colors.muted}>{panel.emptyHint}</Text>
        </Box>
      ) : null}
      {panel.addModal !== null ? (
        <McpAddModal
          state={panel.addModal}
          onJsonChange={onAddJsonChange ?? noop}
          onSubmit={onAddSubmit ?? noopString}
          onCancel={onAddCancel ?? noop}
        />
      ) : (
        <>
          {panel.mode === "list" ? (
            <McpList panel={panel} maxRows={maxRows} />
