it("preserves the current rows and detail through a failed refresh and retry", () => {
  let s = createInitialTuiState();
  s = dispatch(s, {
    type: "mcp_rows_loaded",
    rows: [row("a"), row("docs")],
    emptyHint: null,
    at: 1000,
  });
  s = dispatch(s, { type: "mcp_cursor_set", row: 1 });
  s = dispatch(s, {
    type: "mcp_detail_opened",
    rowKey: "docs",
    detail: detail("docs"),
  });
  s = dispatch(s, { type: "mcp_detail_tab_set", tab: "resources" });
  const beforeRefresh = s.mcpPanel;

  const started = dispatch(s, { type: "mcp_refresh_started" });
  expect(started.mcpPanel).toEqual({
    ...beforeRefresh,
    loading: true,
    lastError: null,
  });

  const failed = dispatch(started, {
    type: "mcp_refresh_failed",
    error: "catalog unavailable",
  });
  expect(failed.mcpPanel).toEqual({
    ...beforeRefresh,
    loading: false,
    lastError: "catalog unavailable",
  });
  expect(started.mcpPanel.loading).toBe(true);
  expect(started.mcpPanel.lastError).toBeNull();

  const retry = dispatch(failed, { type: "mcp_refresh_started" });
  expect(retry.mcpPanel).toEqual({
    ...beforeRefresh,
    loading: true,
    lastError: null,
  });
  expect(failed.mcpPanel.lastError).toBe("catalog unavailable");
});

